using UnityEngine;using UnityEditor;using System.Linq;
public static class InspectTrike{public static string Main(){var go=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/3WheelCar/Piaggio_Ape_FBX_Package/Piaggio_Ape_Articulated.fbx");return "Playing="+Application.isPlaying+"\n"+string.Join("\n",go.GetComponentsInChildren<Transform>().Select(t=>t.name+" pos="+t.position+" rot="+t.eulerAngles+" scale="+t.lossyScale+(t.GetComponent<Renderer>()!=null?" bounds="+t.GetComponent<Renderer>().bounds:"")))+"\nSCENE\n"+string.Join("\n",Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(t=>t.name.ToLower().Contains("piaggio")||t.name.ToLower().Contains("trike")).Select(t=>t.name+" pos="+t.position+" rot="+t.eulerAngles+" scale="+t.lossyScale));}}
